using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    vector<pair<long long, long long>> intervals(n);
    for (auto &[a, b] : intervals) cin >> a >> b;
    sort(intervals.begin(), intervals.end());
    // Merge intervals that intersect or share an endpoint.
    vector<pair<long long, long long>> merged;
    for (auto &[a, b] : intervals) {
        if (!merged.empty() && a <= merged.back().second) merged.back().second = max(merged.back().second, b);
        else merged.push_back({a, b});
    }
    // A bridge of length <= k joins blocks left..right iff merged[right].a - merged[left].b <= k.
    int left = 0, best = 1, m = merged.size();
    for (int right = 0; right < m; right++) {
        while (merged[right].first - merged[left].second > k) left++;
        best = max(best, right - left + 1);
    }
    cout << m - best + 1 << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        // Pack (a, b) into one long so a primitive sort orders by a, then b (both < 2^31).
        long[] intervals = new long[n];
        for (int i = 0; i < n; i++) {
            long a = nextLong(), b = nextLong();
            intervals[i] = a << 31 | b;
        }
        Arrays.sort(intervals);
        long mask = (1L << 31) - 1;
        // Merge intervals that intersect or share an endpoint.
        long[] starts = new long[n], ends = new long[n];
        int m = 0;
        for (long packed : intervals) {
            long a = packed >>> 31, b = packed & mask;
            if (m > 0 && a <= ends[m - 1]) ends[m - 1] = Math.max(ends[m - 1], b);
            else {
                starts[m] = a;
                ends[m] = b;
                m++;
            }
        }
        // A bridge of length <= k joins blocks left..right iff starts[right] - ends[left] <= k.
        int left = 0, best = 1;
        for (int right = 0; right < m; right++) {
            while (starts[right] - ends[left] > k) left++;
            best = Math.max(best, right - left + 1);
        }
        System.out.println(m - best + 1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	intervals := make([][2]int, n)
	for i := range intervals {
		intervals[i] = [2]int{nextInt(), nextInt()}
	}
	sort.Slice(intervals, func(x, y int) bool {
		if intervals[x][0] != intervals[y][0] {
			return intervals[x][0] < intervals[y][0]
		}
		return intervals[x][1] < intervals[y][1]
	})
	// Merge intervals that intersect or share an endpoint.
	merged := make([][2]int, 0, n)
	for _, iv := range intervals {
		if len(merged) > 0 && iv[0] <= merged[len(merged)-1][1] {
			merged[len(merged)-1][1] = max(merged[len(merged)-1][1], iv[1])
		} else {
			merged = append(merged, iv)
		}
	}
	// A bridge of length <= k joins blocks left..right iff merged[right].a - merged[left].b <= k.
	left, best := 0, 1
	for right := range merged {
		for merged[right][0]-merged[left][1] > k {
			left++
		}
		best = max(best, right-left+1)
	}
	fmt.Println(len(merged) - best + 1)
}
